sysml:
// in Anforderungen
requirement <'R-008'> rampenbefahrung {
    doc /* Das FTF befährt Rampen mit einer Steigung von höchstens 4 % mit einer Nutzlast von 500 kg. */
}

// in Verknuepfungen
satisfy Anforderungen::rampenbefahrung by Physik::ftf.fahrwerk;

// in Anforderungen
requirement <'R-008'> rueckwaertsSchutzfeld {
    doc /* Bei Rückwärtsfahrt wird das Schutzfeld hinter dem Fahrzeug überwacht. */
}

// in Physik::ftf
part <'P-009'> scannerHinten : Logik::Sicherheitslaserscanner;

// in Verknuepfungen
satisfy Anforderungen::rueckwaertsSchutzfeld by Physik::ftf.scannerHinten;
